// Cobre: matriz completa de forma × etapa de oxidación × encerado
const COPPER_SHAPES = [
  {es:'Bloque de Cobre', en:'Block of Copper', base:true},
  {es:'Cobre Cortado', en:'Cut Copper'},
  {es:'Losa de Cobre Cortado', en:'Cut Copper Slab'},
  {es:'Escalera de Cobre Cortado', en:'Cut Copper Stairs'},
  {es:'Puerta de Cobre', en:'Copper Door'},
  {es:'Trampilla de Cobre', en:'Copper Trapdoor'},
  {es:'Rejilla de Cobre', en:'Copper Grate'},
  {es:'Lámpara de Cobre', en:'Copper Bulb'},
  // Nuevos en 1.21.9 "La Era del Cobre"
  {es:'Cofre de Cobre', en:'Copper Chest'},
  {es:'Estatua de Gólem de Cobre', en:'Copper Golem Statue'},
  {es:'Barrotes de Cobre', en:'Copper Bars'},
  {es:'Cadena de Cobre', en:'Copper Chain'},
  {es:'Farol de Cobre', en:'Copper Lantern'},
];
const COPPER_STAGES = [
  {es:'', en:''}, {es:'Expuesto', en:'Exposed'}, {es:'Deteriorado', en:'Weathered'}, {es:'Oxidado', en:'Oxidized'},
];
const COBRE = (() => {
  const list = [
    ['Mena de Cobre','Copper Ore',64],['Mena de Cobre (Pizarra Profunda)','Deepslate Copper Ore',64],
    ['Cobre en Bruto','Raw Copper',64],['Bloque de Cobre en Bruto','Raw Copper Block',64],
    ['Lingote de Cobre','Copper Ingot',64],
    // Nuevos en 1.21.9 "La Era del Cobre"
    ['Pepita de Cobre','Copper Nugget',64],['Antorcha de Cobre','Copper Torch',64],
  ];
  COPPER_SHAPES.forEach(shape=>{
    COPPER_STAGES.forEach(stage=>{
      [false, true].forEach(waxed=>{
        const labelEs = shape.es + (stage.es ? ' '+stage.es : '') + (waxed ? ' Encerado' : '');
        let baseEn;
        if(shape.base){
          baseEn = stage.en ? `${stage.en} Copper` : 'Block of Copper';
        } else {
          baseEn = stage.en ? `${stage.en} ${shape.en}` : shape.en;
        }
        const labelEn = waxed ? `Waxed ${baseEn}` : baseEn;
        list.push([labelEs, labelEn, 64]);
      });
    });
  });
  return list;
})();

