function crossIconsHTML(label, dimKey){
  const dims = SHARED_LABELS[label];
  if(!dims) return '';
  const others = dims.filter(d=>d!==dimKey);
  if(!others.length) return '';
  return others.map(d=>`<img class="dim-tag" src="${DIM_ICON_IMG[d]}" title="${escAttr(DIM_ICON[d].titleEn+' / '+DIM_ICON[d].titleEs)}" alt="${d}">`).join('');
}

/* ================= NO APILABLES EXTRACTION ================= */

function extractNoApilables(sec){
  const extracted = [];
  if(sec.items){
    const keep = [];
    sec.items.forEach(it=>{ if(it[2]===1) extracted.push(it); else keep.push(it); });
    sec.items = keep;
  }
  if(sec.subs){
    sec.subs.forEach(sub=>{
      const keep = [];
      sub.items.forEach(it=>{ if(it[2]===1) extracted.push(it); else keep.push(it); });
      sub.items = keep;
    });
    sec.subs = sec.subs.filter(sub=>sub.items.length>0);
  }
  if(extracted.length){
    if(!sec.subs) sec.subs = [];
    sec.subs.push({nameEs:'⛔ No Apilables', nameEn:'⛔ Non-Stackable', items:extracted, noApil:true});
  }
  return sec;
}

