/* ================= RENDER ================= */

const usedIds = new Set();
function slotId(ctx, label){
  let base = 'it_'+(ctx+'_'+label).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');
  let id = base, n = 1;
  while(usedIds.has(id)){ id = base+'_'+(n++); }
  usedIds.add(id);
  return id;
}

