function itemIconHTML(enLabel){
  const idx = LABEL_ICON_IDX[enLabel];
  if(idx===undefined) return '<span class="item-icon item-icon-empty" aria-hidden="true"></span>';
  return `<img class="item-icon" src="data:image/png;base64,${TEX_ICONS[idx]}" alt="" loading="lazy">`;
}

function renderItems(items, dimKey, ctx){
  return items.map(([esLabel, enLabel, stack])=>{
    const id = slotId(ctx, esLabel);
    LABELS_BY_ID[id] = {es: esLabel, en: enLabel};
    const cls = stack===64?'s64':(stack===16?'s16':'s1');
    const label = LANG==='en' ? enLabel : esLabel;
    return `<label class="item-row" data-label="${label.toLowerCase()}">
      <input type="checkbox" class="slot" id="${id}">
      ${itemIconHTML(enLabel)}
      <span class="item-label">${label}</span>
      <span class="dim-icons">${crossIconsHTML(esLabel, dimKey)}</span>
      <span class="stack-tag ${cls}">x${stack}</span>
    </label>`;
  }).join('');
}

function renderSection(sec, dimKey){
  let body = '';
  const secCtx = dimKey+'_'+sec.nameEs;
  if(sec.items){
    body += `<div class="items-flat">${renderItems(sec.items, dimKey, secCtx)}</div>`;
  }
  if(sec.subs){
    body += sec.subs.map(sub=>`
      <details class="sub${sub.noApil?' sub-noapil':''}" open>
        <summary>
          <span class="sub-caret">▶</span>
          <span class="sub-name" data-es="${escAttr(sub.nameEs)}" data-en="${escAttr(sub.nameEn)}">${LANG==='en'?sub.nameEn:sub.nameEs}</span>
          <span class="sub-count" data-subcount></span>
        </summary>
        <div class="sub-body">${renderItems(sub.items, dimKey, secCtx+'_'+sub.nameEs)}</div>
      </details>`).join('');
  }
  if(sec.noteEs){
    body += `<div class="note" data-es="${escAttr(sec.noteEs)}" data-en="${escAttr(sec.noteEn)}">${LANG==='en'?sec.noteEn:sec.noteEs}</div>`;
  }
  return `
    <details class="section" open>
      <summary>
        <div class="sec-left">
          <span class="sec-caret">▶</span>
          <span class="sec-name" data-icon="${sec.icon}" data-es="${escAttr(sec.nameEs)}" data-en="${escAttr(sec.nameEn)}">${sec.icon} ${LANG==='en'?sec.nameEn:sec.nameEs}</span>
        </div>
        <div class="sec-bar"><div class="sec-bar-fill" data-secbar></div></div>
        <div class="sec-count" data-seccount></div>
        <div class="sec-actions">
          <button type="button" class="mini-btn" data-check-all data-es="TODO" data-en="ALL">${LANG==='en'?'ALL':'TODO'}</button>
          <button type="button" class="mini-btn" data-check-none data-es="NADA" data-en="NONE">${LANG==='en'?'NONE':'NADA'}</button>
        </div>
      </summary>
      <div class="sec-body">${body}</div>
    </details>`;
}

document.getElementById('sections').innerHTML = Object.values(DIM_META).map(dim=>`
  <div class="dim-panel" data-dim="${dim.key}">
    ${dim.sections.map(sec=>renderSection(sec, dim.key)).join('')}
  </div>`).join('');

document.getElementById('dimTabs').innerHTML = Object.values(DIM_META).map(dim=>`
  <button type="button" class="dim-tab" data-dim="${dim.key}">
    <span class="dt-name">${dim.icon} <span data-es="${escAttr(dim.labelEs)}" data-en="${escAttr(dim.labelEn)}">${LANG==='en'?dim.labelEn:dim.labelEs}</span></span>
    <span class="dt-count" data-dtcount>0 / 0</span>
    <div class="dt-bar"><div class="dt-bar-fill" data-dtbar></div></div>
  </button>`).join('');

function setActiveDim(dimKey){
  document.querySelectorAll('.dim-panel').forEach(p=>p.classList.toggle('active-panel', p.dataset.dim===dimKey));
  document.querySelectorAll('.dim-tab').forEach(b=>b.classList.toggle('active-tab', b.dataset.dim===dimKey));
  document.getElementById('dimTitle').textContent = DIM_META[dimKey].fullTitle;
}
document.getElementById('dimTabs').addEventListener('click', e=>{
  const btn = e.target.closest('[data-dim]');
  if(!btn) return;
  setActiveDim(btn.dataset.dim);
});
setActiveDim('overworld');

/* ---- view mode switch (checklist vs storage layout) ---- */
function setMode(mode){
  const isLayout = mode==='layout';
  document.getElementById('dimTabs').classList.toggle('hidden', isLayout);
  document.getElementById('checklistOnly1').classList.toggle('hidden', isLayout);
  document.getElementById('searchResultsNote').classList.toggle('hidden', isLayout);
  document.getElementById('checklistOnly2').classList.toggle('hidden', isLayout);
  document.getElementById('dimLegend').classList.toggle('hidden', isLayout);
  document.getElementById('sections').classList.toggle('hidden', isLayout);
  document.getElementById('layoutPanel').classList.toggle('active-panel', isLayout);
  document.querySelectorAll('.mode-tab').forEach(b=>b.classList.toggle('active-mode', b.dataset.mode===mode));
  // the viewport is hidden (display:none) until this tab is opened, so its size is
  // only known once it becomes visible — (re)fit the map the first few times it's shown
  if(isLayout && typeof crossResetView === 'function' && !window.__crossEverFit){
    requestAnimationFrame(()=>requestAnimationFrame(()=>{ crossResetView(); window.__crossEverFit = true; }));
  }
}
document.getElementById('modeTabs').addEventListener('click', e=>{
  const btn = e.target.closest('[data-mode]');
  if(!btn) return;
  setMode(btn.dataset.mode);
});

/* ================= LOGIC ================= */

function updateCounts(){
  let totalAll=0, doneAll=0;
  document.querySelectorAll('.dim-panel').forEach(panelEl=>{
    let panelTotal=0, panelDone=0;
    panelEl.querySelectorAll('details.section').forEach(sectionEl=>{
      const boxes = sectionEl.querySelectorAll('.slot');
      let done=0;
      boxes.forEach(b=>{ if(b.checked) done++; });
      const total = boxes.length;
      panelTotal+=total; panelDone+=done;
      const bar = sectionEl.querySelector(':scope > summary [data-secbar]');
      const cnt = sectionEl.querySelector(':scope > summary [data-seccount]');
      if(bar) bar.style.width = total? (done/total*100)+'%':'0%';
      if(cnt) cnt.textContent = done+'/'+total;

      sectionEl.querySelectorAll('details.sub').forEach(subEl=>{
        const sboxes = subEl.querySelectorAll('.slot');
        let sdone=0;
        sboxes.forEach(b=>{ if(b.checked) sdone++; });
        const c = subEl.querySelector('[data-subcount]');
        if(c) c.textContent = sdone+'/'+sboxes.length;
      });
    });
    totalAll+=panelTotal; doneAll+=panelDone;
    const dimKey = panelEl.dataset.dim;
    const tabBtn = document.querySelector(`.dim-tab[data-dim="${dimKey}"]`);
    if(tabBtn){
      const dc = tabBtn.querySelector('[data-dtcount]');
      const db = tabBtn.querySelector('[data-dtbar]');
      if(dc) dc.textContent = panelDone+' / '+panelTotal;
      if(db) db.style.width = panelTotal? (panelDone/panelTotal*100)+'%':'0%';
    }
  });
  document.getElementById('xpFill').style.width = totalAll? (doneAll/totalAll*100)+'%':'0%';
  const suffix = LANG==='en' ? ' collected (all dimensions)' : ' recolectados (todas las dimensiones)';
  document.getElementById('xpCount').textContent = doneAll+' / '+totalAll+suffix;
}

document.getElementById('sections').addEventListener('change', e=>{
  if(e.target.classList.contains('slot')){
    e.target.closest('.item-row').classList.toggle('done', e.target.checked);
    updateCounts();
    autoSave();
    if(missingOnlyToggle.checked) runSearch();
  }
});

document.getElementById('sections').addEventListener('click', e=>{
  const btn = e.target.closest('[data-check-all],[data-check-none]');
  if(!btn) return;
  e.preventDefault();
  const section = btn.closest('details.section');
  const val = btn.hasAttribute('data-check-all');
  const boxes = [...section.querySelectorAll('.slot')];

  if(!val){
    const checkedCount = boxes.filter(b=>b.checked).length;
    if(checkedCount>0){
      const secName = section.querySelector(':scope > summary .sec-name').textContent.trim();
      const msg = LANG==='en'
        ? `Clear ${checkedCount} checked item(s) in "${secName}"? This can't be undone.`
        : `¿Vaciar ${checkedCount} ítem(s) marcados en "${secName}"? No se puede deshacer.`;
      if(!confirm(msg)) return;
    }
  }

  boxes.forEach(b=>{
    b.checked = val;
    b.closest('.item-row').classList.toggle('done', val);
  });
  updateCounts();
  autoSave();
});

/* ---- Expand all / Collapse all ---- */
document.getElementById('expandAllBtn').addEventListener('click', ()=>{
  document.querySelectorAll('.dim-panel.active-panel details').forEach(d=>d.open=true);
});
document.getElementById('collapseAllBtn').addEventListener('click', ()=>{
  document.querySelectorAll('.dim-panel.active-panel details.section').forEach(d=>d.open=false);
});

/* ---- "/" keyboard shortcut focuses search ---- */
document.addEventListener('keydown', e=>{
  if(e.key==='/' && document.activeElement!==searchInput &&
     !['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){
    e.preventDefault();
    searchInput.focus();
  }
});

/* ---- "Show missing only" toggle ---- */
const missingOnlyToggle = document.getElementById('missingOnlyToggle');
missingOnlyToggle.addEventListener('change', runSearch);

const searchInput = document.getElementById('search');
const searchClearBtn = document.getElementById('searchClear');
const searchNote = document.getElementById('searchResultsNote');

function runSearch(){
  const q = searchInput.value.trim().toLowerCase();
  const missingOnly = missingOnlyToggle.checked;
  searchClearBtn.style.display = q ? 'block' : 'none';

  let totalMatches = 0;
  document.querySelectorAll('.item-row').forEach(row=>{
    const textMatch = !q || row.dataset.label.includes(q);
    const cb = row.querySelector('.slot');
    const missingMatch = !missingOnly || !cb.checked;
    const match = textMatch && missingMatch;
    row.classList.toggle('hidden', !match);
    if(q && match) totalMatches++;
  });
  document.querySelectorAll('details.sub').forEach(sub=>{
    const anyVisible = [...sub.querySelectorAll('.item-row')].some(r=>!r.classList.contains('hidden'));
    sub.classList.toggle('hidden', !anyVisible);
    if(q && anyVisible) sub.open = true;
  });
  document.querySelectorAll('details.section').forEach(sec=>{
    const anyVisible = [...sec.querySelectorAll('.item-row')].some(r=>!r.classList.contains('hidden'));
    sec.classList.toggle('hidden', !anyVisible);
    if(q && anyVisible) sec.open = true;
  });

  const rawQ = searchInput.value.trim();
  if(!q){
    searchNote.textContent = '';
  }else if(totalMatches===0){
    searchNote.textContent = LANG==='en'
      ? `No results for "${rawQ}" in any dimension.`
      : `Sin resultados para "${rawQ}" en ninguna dimensión.`;
  }else{
    searchNote.textContent = LANG==='en'
      ? `${totalMatches} result${totalMatches===1?'':'s'} for "${rawQ}" (across all 3 dimensions).`
      : `${totalMatches} resultado${totalMatches===1?'':'s'} para "${rawQ}" (contando las 3 dimensiones).`;
  }
}

searchInput.addEventListener('input', runSearch);
searchClearBtn.addEventListener('click', ()=>{
  searchInput.value = '';
  runSearch();
  searchInput.focus();
});

const STORAGE_KEY = 'mc_all_dimensions_checklist_v3';

function storageAvailable(){
  try{
    const k = '__test__';
    localStorage.setItem(k,'1');
    localStorage.removeItem(k);
    return true;
  }catch(e){ return false; }
}
const AUTOSAVE = storageAvailable();

function autoSave(){
  if(!AUTOSAVE) return;
  try{
    const checked = [...document.querySelectorAll('.slot')].filter(b=>b.checked).map(b=>b.id);
    localStorage.setItem(STORAGE_KEY, JSON.stringify({savedAt:new Date().toISOString(), checked}));
  }catch(e){ /* silencioso: si falla, quedan los botones manuales */ }
}

function autoLoad(){
  if(!AUTOSAVE) return;
  try{
    const raw = localStorage.getItem(STORAGE_KEY);
    if(!raw) return;
    const data = JSON.parse(raw);
    const ids = new Set(data.checked || []);
    document.querySelectorAll('.slot').forEach(b=>{
      const on = ids.has(b.id);
      b.checked = on;
      b.closest('.item-row').classList.toggle('done', on);
    });
  }catch(e){ /* silencioso */ }
}

/* ================= CROSS STORAGE LAYOUT ================= */
/* Each arm is a two-wall corridor: side "A" and side "B" flank the black
   road in parallel (A/B = West/East wall for the N/S arms, North/South wall
   for the E/W arms). Each wall now has TWO parallel rows of slots — depth 0
   (inner, right next to the road) and depth 1 (outer, one row further back)
   — like a second rank of item frames behind the first. A "group" adds 8
   rungs, i.e. 8 slots to EACH of the 4 rows (A-inner, A-outer, B-inner,
   B-outer), never a single-file line. */

const GROUP_SIZE = 8;
const MAX_GROUPS = 16;
const DEPTHS = [0, 1]; // 0 = inner row (next to road), 1 = outer row (behind it)

const ARM_META = {
  N: {es:'Norte', en:'North'},
  S: {es:'Sur', en:'South'},
  E: {es:'Este', en:'East'},
  W: {es:'Oeste', en:'West'},
};

// Friendly wall names per arm orientation (vertical arms flank East/West, horizontal arms flank North/South)
const SIDE_META = {
  N: { A:{es:'Pared Oeste', en:'West Wall'}, B:{es:'Pared Este',  en:'East Wall'} },
  S: { A:{es:'Pared Oeste', en:'West Wall'}, B:{es:'Pared Este',  en:'East Wall'} },
  E: { A:{es:'Pared Norte', en:'North Wall'}, B:{es:'Pared Sur',  en:'South Wall'} },
  W: { A:{es:'Pared Norte', en:'North Wall'}, B:{es:'Pared Sur',  en:'South Wall'} },
};

const DEPTH_META = {
  0: {es:'Fila interior', en:'Inner row'},
  1: {es:'Fila exterior', en:'Outer row'},
};

function freshArm(){
  return {
    A: [Array(GROUP_SIZE).fill(''), Array(GROUP_SIZE).fill('')],
    B: [Array(GROUP_SIZE).fill(''), Array(GROUP_SIZE).fill('')],
  };
}
function freshLayout(){ return { N: freshArm(), S: freshArm(), E: freshArm(), W: freshArm() }; }

let CROSS_LAYOUT = freshLayout();
let selectedSlot = null; // {arm, side, depth, idx}

const CROSS_KEY = 'mc_cross_layout_v3';
const CROSS_KEY_LEGACY = 'mc_cross_layout_v2'; // old single-row format, migrated in as the inner row

function isValidArmData(arm){
  if(!arm) return false;
  return ['A','B'].every(side=>{
    const d = arm[side];
    return Array.isArray(d) && d.length===2
      && Array.isArray(d[0]) && Array.isArray(d[1])
      && d[0].length === d[1].length
      && d[0].length > 0 && d[0].length % GROUP_SIZE === 0;
  }) && arm.A[0].length === arm.B[0].length;
}

function isLegacyArmData(arm){
  return arm && Array.isArray(arm.A) && Array.isArray(arm.B)
    && arm.A.length === arm.B.length && arm.A.length > 0
    && typeof arm.A[0] !== 'object';
}
function migrateLegacyArm(arm){
  return {
    A: [arm.A.slice(), Array(arm.A.length).fill('')],
    B: [arm.B.slice(), Array(arm.B.length).fill('')],
  };
}

function crossSave(){
  if(!AUTOSAVE) return;
  try{ localStorage.setItem(CROSS_KEY, JSON.stringify(CROSS_LAYOUT)); }catch(e){}
}
function crossLoadFromStorage(){
  if(!AUTOSAVE) return;
  try{
    const raw = localStorage.getItem(CROSS_KEY);
    if(raw){
      const data = JSON.parse(raw);
      ['N','S','E','W'].forEach(arm=>{
        if(isValidArmData(data[arm])) CROSS_LAYOUT[arm] = data[arm];
      });
      return;
    }
    // no v3 data yet — try migrating an old v2 (single-row) layout, if present
    const legacyRaw = localStorage.getItem(CROSS_KEY_LEGACY);
    if(!legacyRaw) return;
    const legacyData = JSON.parse(legacyRaw);
    ['N','S','E','W'].forEach(arm=>{
      if(isLegacyArmData(legacyData[arm])) CROSS_LAYOUT[arm] = migrateLegacyArm(legacyData[arm]);
    });
    crossSave();
  }catch(e){}
}

function refreshItemsDatalist(){
  const names = new Set();
  Object.values(LABELS_BY_ID).forEach(o=>names.add(LANG==='en' ? o.en : o.es));
  const sorted = [...names].sort((a,b)=>a.localeCompare(b));
  document.getElementById('crossItemsList').innerHTML = sorted.map(n=>`<option value="${escAttr(n)}"></option>`).join('');
}

function armGroups(arm){ return CROSS_LAYOUT[arm].A[0].length / GROUP_SIZE; }

function addCrossGroup(arm){
  if(armGroups(arm) >= MAX_GROUPS) return;
  ['A','B'].forEach(side=>{
    DEPTHS.forEach(d=>{
      CROSS_LAYOUT[arm][side][d] = CROSS_LAYOUT[arm][side][d].concat(Array(GROUP_SIZE).fill(''));
    });
  });
  crossSave();
  renderCross();
}
function removeCrossGroup(arm){
  if(armGroups(arm) <= 1) return;
  const hasData = ['A','B'].some(side=>DEPTHS.some(d=>
    CROSS_LAYOUT[arm][side][d].slice(-GROUP_SIZE).some(v=>v)
  ));
  if(hasData){
    const msg = LANG==='en'
      ? 'The last group has assigned items. Remove it anyway?'
      : 'El último grupo tiene ítems asignados. ¿Quitarlo igual?';
    if(!confirm(msg)) return;
  }
  ['A','B'].forEach(side=>{
    DEPTHS.forEach(d=>{
      CROSS_LAYOUT[arm][side][d] = CROSS_LAYOUT[arm][side][d].slice(0, -GROUP_SIZE);
    });
  });
  if(selectedSlot && selectedSlot.arm===arm && selectedSlot.idx >= CROSS_LAYOUT[arm].A[0].length){
    closeCrossEditor();
  }
  crossSave();
  renderCross();
}

// Renders one rung: for N/S arms a horizontal row, for E/W arms a vertical column,
// always laid out as [A-outer][A-inner][road][B-inner][B-outer] — two ranks of slots
// flanking each side of the road, never single-file.
// kind: 'slot' (normal), 'cap' (red end/group marker on all 4 rows, road still continuous)
let LABEL_TEXT_TO_ICON = null;
function buildLabelTextToIcon(){
  LABEL_TEXT_TO_ICON = {};
  Object.values(LABELS_BY_ID).forEach(o=>{
    const idx = LABEL_ICON_IDX[o.en];
    if(idx===undefined) return;
    LABEL_TEXT_TO_ICON[o.es] = idx;
    LABEL_TEXT_TO_ICON[o.en] = idx;
  });
}
function iconDataUriForLabel(text){
  if(!LABEL_TEXT_TO_ICON) buildLabelTextToIcon();
  const idx = LABEL_TEXT_TO_ICON[text];
  return idx===undefined ? null : `data:image/png;base64,${TEX_ICONS[idx]}`;
}

function renderRung(arm, idx, vertical, kind){
  const wrapClass = vertical ? 'rung-v' : 'rung-h';
  const roadClass = vertical ? 'rung-road-v' : 'rung-road-h';
  if(kind === 'cap'){
    const cap = '<div class="cross-cap"></div>';
    return `<div class="${wrapClass}">${cap}${cap}<div class="${roadClass}"></div>${cap}${cap}</div>`;
  }
  const slotHtml = (side, depth)=>{
    const val = CROSS_LAYOUT[arm][side][depth][idx];
    const isSel = selectedSlot && selectedSlot.arm===arm && selectedSlot.side===side && selectedSlot.depth===depth && selectedSlot.idx===idx;
    const emptyTitle = LANG==='en' ? 'Empty slot' : 'Slot vacío';
    if(val){
      const icon = iconDataUriForLabel(val);
      const styleAttr = icon ? ` style="background-image:url('${icon}')"` : '';
      const inner = icon ? '' : escAttr(val);
      return `<button type="button" class="cross-slot filled${icon?' has-icon':''}${isSel?' selected':''}" data-arm="${arm}" data-side="${side}" data-depth="${depth}" data-idx="${idx}" title="${escAttr(val)}"${styleAttr}>${inner}</button>`;
    }
    return `<button type="button" class="cross-slot${isSel?' selected':''}" data-arm="${arm}" data-side="${side}" data-depth="${depth}" data-idx="${idx}" title="${emptyTitle}"><span class="cs-empty">+</span></button>`;
  };
  return `<div class="${wrapClass}">${slotHtml('A',1)}${slotHtml('A',0)}<div class="${roadClass}"></div>${slotHtml('B',0)}${slotHtml('B',1)}</div>`;
}

function renderArmSlots(arm){
  const vertical = (arm==='N'||arm==='S');
  const spacerClass = vertical ? 'arm-spacer-v' : 'arm-spacer-h';
  let html = `<div class="${spacerClass}"></div>`; // gap next to the hub, so walls never touch at the corners
  const rungs = CROSS_LAYOUT[arm].A[0].length;
  for(let idx=0; idx<rungs; idx++){
    if(idx>0 && idx % GROUP_SIZE === 0) html += renderRung(arm, idx, vertical, 'cap'); // group boundary
    html += renderRung(arm, idx, vertical, 'slot');
  }
  html += renderRung(arm, rungs, vertical, 'cap'); // closing tip cap
  html += `<div class="arm-controls">
    <button type="button" class="arm-btn" data-arm-add="${arm}" title="${LANG==='en'?'Add group (8 rungs)':'Agregar grupo (8 rungs)'}">＋</button>
    <button type="button" class="arm-btn" data-arm-remove="${arm}" title="${LANG==='en'?'Remove group (8 rungs)':'Quitar grupo (8 rungs)'}">－</button>
  </div>`;
  return html;
}

function renderCross(){
  const grid = document.getElementById('crossGrid');
  if(!grid) return;
  grid.innerHTML = `
    <div class="cross-road-v"></div>
    <div class="cross-road-h"></div>
    <div class="arm-n">${renderArmSlots('N')}</div>
    <div class="arm-w">${renderArmSlots('W')}</div>
    <div class="cross-hub" title="${LANG==='en'?'Storage hub':'Centro de almacén'}">📦</div>
    <div class="arm-e">${renderArmSlots('E')}</div>
    <div class="arm-s">${renderArmSlots('S')}</div>
  `;
}

function updateCrossEditorPreview(){
  const preview = document.getElementById('crossEditorPreview');
  const input = document.getElementById('crossEditorInput');
  if(!preview || !input) return;
  const icon = iconDataUriForLabel(input.value.trim());
  if(icon){
    preview.src = icon;
    preview.classList.add('shown');
  }else{
    preview.classList.remove('shown');
    preview.removeAttribute('src');
  }
}

function openCrossEditor(arm, side, depth, idx){
  selectedSlot = {arm, side, depth, idx};
  renderCross();
  const editor = document.getElementById('crossEditor');
  const label = document.getElementById('crossEditorLabel');
  const input = document.getElementById('crossEditorInput');
  const armLabel = ARM_META[arm][LANG];
  const sideLabel = SIDE_META[arm][side][LANG];
  const depthLabel = DEPTH_META[depth][LANG];
  label.textContent = (LANG==='en' ? 'Editing' : 'Editando') + `: ${armLabel} · ${sideLabel} · ${depthLabel} · #${idx+1}`;
  input.value = CROSS_LAYOUT[arm][side][depth][idx] || '';
  editor.classList.add('active');
  updateCrossEditorPreview();
  input.focus();
  input.select();
}
function closeCrossEditor(){
  selectedSlot = null;
  document.getElementById('crossEditor').classList.remove('active');
  renderCross();
}
function commitCrossEditor(){
  if(!selectedSlot) return;
  const val = document.getElementById('crossEditorInput').value.trim();
  CROSS_LAYOUT[selectedSlot.arm][selectedSlot.side][selectedSlot.depth][selectedSlot.idx] = val;
  crossSave();
  closeCrossEditor();
}
function clearCrossEditor(){
  if(!selectedSlot) return;
  CROSS_LAYOUT[selectedSlot.arm][selectedSlot.side][selectedSlot.depth][selectedSlot.idx] = '';
  crossSave();
  closeCrossEditor();
}

document.getElementById('crossGrid').addEventListener('click', e=>{
  if(crossJustDragged){ crossJustDragged = false; return; } // swallow the click that follows a pan/pinch drag
  const addBtn = e.target.closest('[data-arm-add]');
  if(addBtn){ addCrossGroup(addBtn.dataset.armAdd); return; }
  const rmBtn = e.target.closest('[data-arm-remove]');
  if(rmBtn){ removeCrossGroup(rmBtn.dataset.armRemove); return; }
  const slot = e.target.closest('.cross-slot');
  if(slot){ openCrossEditor(slot.dataset.arm, slot.dataset.side, parseInt(slot.dataset.depth,10), parseInt(slot.dataset.idx,10)); }
});

document.getElementById('crossSaveBtn').addEventListener('click', commitCrossEditor);
document.getElementById('crossClearBtn').addEventListener('click', clearCrossEditor);
document.getElementById('crossCancelBtn').addEventListener('click', closeCrossEditor);
document.getElementById('crossEditorInput').addEventListener('keydown', e=>{
  if(e.key==='Enter'){ e.preventDefault(); commitCrossEditor(); }
  else if(e.key==='Escape'){ e.preventDefault(); closeCrossEditor(); }
});
document.getElementById('crossEditorInput').addEventListener('input', updateCrossEditorPreview);

document.getElementById('crossResetBtn').addEventListener('click', ()=>{
  const anyData = ['N','S','E','W'].some(arm=>
    ['A','B'].some(side=>DEPTHS.some(d=>CROSS_LAYOUT[arm][side][d].some(v=>v)))
  );
  if(anyData){
    const msg = LANG==='en' ? 'Clear the entire storage room layout? This can\'t be undone.' : '¿Vaciar todo el diseño de la sala de almacén? No se puede deshacer.';
    if(!confirm(msg)) return;
  }
  CROSS_LAYOUT = freshLayout();
  closeCrossEditor();
  crossSave();
  renderCross();
});

crossLoadFromStorage();
renderCross();

/* ================= CROSS MAP: PAN & ZOOM ================= */
/* Turns the storage-room grid into a draggable, zoomable "map" — like a
   full image you can navigate — instead of relying on page scrollbars. */

const crossViewport = document.getElementById('crossViewport');
const crossStage = document.getElementById('crossStage');
const crossZoomPct = document.getElementById('crossZoomPct');

const CROSS_MIN_SCALE = 0.25;
const CROSS_MAX_SCALE = 2.5;
let crossView = { scale: 1, x: 0, y: 0 };
let crossJustDragged = false; // set true once a drag/pinch moves past a small threshold

function applyCrossView(){
  if(!crossStage) return;
  crossStage.style.transform = `translate(${crossView.x}px, ${crossView.y}px) scale(${crossView.scale})`;
  if(crossZoomPct) crossZoomPct.textContent = Math.round(crossView.scale * 100) + '%';
}
function clampCrossScale(s){ return Math.min(CROSS_MAX_SCALE, Math.max(CROSS_MIN_SCALE, s)); }

// Zoom while keeping the given viewport-relative point (px, py) visually fixed in place.
function crossZoomAt(factor, px, py){
  const newScale = clampCrossScale(crossView.scale * factor);
  const ratio = newScale / crossView.scale;
  crossView.x = px - ratio * (px - crossView.x);
  crossView.y = py - ratio * (py - crossView.y);
  crossView.scale = newScale;
  applyCrossView();
}
function crossZoomAtCenter(factor){
  if(!crossViewport) return;
  crossZoomAt(factor, crossViewport.clientWidth / 2, crossViewport.clientHeight / 2);
}
function crossResetView(){
  if(!crossViewport || !crossStage) return;
  const vw = crossViewport.clientWidth, vh = crossViewport.clientHeight;
  const sw = crossStage.scrollWidth || crossStage.offsetWidth;
  const sh = crossStage.scrollHeight || crossStage.offsetHeight;
  // fit the whole map in view, but never zoom in past 100% just to fill space
  const fitScale = Math.min(vw / Math.max(sw,1), vh / Math.max(sh,1), 1);
  crossView.scale = clampCrossScale(fitScale || 1);
  crossView.x = (vw - sw * crossView.scale) / 2;
  crossView.y = (vh - sh * crossView.scale) / 2;
  applyCrossView();
}

if(crossViewport && crossStage){
  // --- drag to pan (mouse + touch, via Pointer Events) ---
  const activePointers = new Map(); // pointerId -> {x,y}
  let panState = null;   // {x, y, ox, oy}
  let pinchState = null; // {dist, scale, midX, midY}
  let moveDistance = 0;

  function midpoint(pts){ return { x:(pts[0].x+pts[1].x)/2, y:(pts[0].y+pts[1].y)/2 }; }
  function dist(pts){ return Math.hypot(pts[0].x-pts[1].x, pts[0].y-pts[1].y); }

  // NOTE: pointer capture is only claimed once real dragging is detected (see
  // pointermove below) — capturing immediately on pointerdown would retarget the
  // 'click' event in Chromium and silently break single-tap clicks on the slots.
  let capturedPointerId = null;

  crossViewport.addEventListener('pointerdown', e=>{
    if(e.button !== undefined && e.button > 0) return; // ignore right/middle click
    if(e.target.closest('.cross-zoom-controls')) return; // let the zoom buttons work normally
    activePointers.set(e.pointerId, {x:e.clientX, y:e.clientY});
    moveDistance = 0;
    if(activePointers.size === 1){
      panState = { x:e.clientX, y:e.clientY, ox:crossView.x, oy:crossView.y };
    }else if(activePointers.size === 2){
      panState = null;
      const pts = [...activePointers.values()];
      const rect = crossViewport.getBoundingClientRect();
      const mid = midpoint(pts);
      pinchState = { dist: dist(pts), scale: crossView.scale, midX: mid.x - rect.left, midY: mid.y - rect.top };
      if(capturedPointerId === null){ crossViewport.setPointerCapture(e.pointerId); capturedPointerId = e.pointerId; }
      crossViewport.classList.add('dragging');
    }
  });

  crossViewport.addEventListener('pointermove', e=>{
    if(!activePointers.has(e.pointerId)) return;
    activePointers.set(e.pointerId, {x:e.clientX, y:e.clientY});

    if(activePointers.size === 2 && pinchState){
      const pts = [...activePointers.values()];
      const factor = dist(pts) / (pinchState.dist || 1);
      const newScale = clampCrossScale(pinchState.scale * factor);
      const ratio = newScale / crossView.scale;
      crossView.x = pinchState.midX - ratio * (pinchState.midX - crossView.x);
      crossView.y = pinchState.midY - ratio * (pinchState.midY - crossView.y);
      crossView.scale = newScale;
      applyCrossView();
      moveDistance += 5; // pinch always counts as a drag, never a click
    }else if(activePointers.size === 1 && panState){
      const dx = e.clientX - panState.x;
      const dy = e.clientY - panState.y;
      if(!capturedPointerId && (Math.abs(dx) + Math.abs(dy)) > 4){
        // real drag detected — claim capture now so the pan keeps tracking even
        // if the pointer leaves the viewport bounds
        crossViewport.setPointerCapture(e.pointerId);
        capturedPointerId = e.pointerId;
        crossViewport.classList.add('dragging');
      }
      moveDistance += Math.abs(dx) + Math.abs(dy);
      crossView.x = panState.ox + dx;
      crossView.y = panState.oy + dy;
      applyCrossView();
    }
  });

  function crossPointerEnd(e){
    activePointers.delete(e.pointerId);
    if(activePointers.size < 2) pinchState = null;
    if(e.pointerId === capturedPointerId) capturedPointerId = null;
    if(activePointers.size === 0){
      panState = null;
      crossViewport.classList.remove('dragging');
      if(moveDistance > 6) crossJustDragged = true; // suppress the click that follows on the slot underneath
    }
  }
  crossViewport.addEventListener('pointerup', crossPointerEnd);
  crossViewport.addEventListener('pointercancel', crossPointerEnd);
  crossViewport.addEventListener('pointerleave', crossPointerEnd);

  // --- wheel to zoom (desktop) ---
  crossViewport.addEventListener('wheel', e=>{
    e.preventDefault();
    const rect = crossViewport.getBoundingClientRect();
    const factor = e.deltaY < 0 ? 1.12 : 1/1.12;
    crossZoomAt(factor, e.clientX - rect.left, e.clientY - rect.top);
  }, { passive:false });

  // --- zoom buttons ---
  document.getElementById('crossZoomIn').addEventListener('click', ()=>crossZoomAtCenter(1.25));
  document.getElementById('crossZoomOut').addEventListener('click', ()=>crossZoomAtCenter(1/1.25));
  document.getElementById('crossZoomFit').addEventListener('click', crossResetView);

  // fade the corner hint out after first interaction
  const hint = document.getElementById('crossViewportHint');
  crossViewport.addEventListener('pointerdown', ()=>{ if(hint) hint.style.display = 'none'; }, { once:true });

  // initial fit (only if the layout tab happens to already be visible on load)
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    if(crossViewport.clientWidth > 0){ crossResetView(); window.__crossEverFit = true; }
  }));
  window.addEventListener('resize', ()=>{ /* keep current pan/zoom on resize; user can hit ⤢ to re-fit */ });
}

/* ================= LANGUAGE STRINGS ================= */

const LEGEND_HTML = {
  es: '',
  en: '',
};

const FOOTER_TEXT = {
  es: 'Guardado automático solo funciona al abrir este archivo directo en tu navegador (no en la vista previa de Claude.ai). Los botones de arriba siempre funcionan como respaldo manual.',
  en: "Autosave only works when you open this file directly in your browser (not in the Claude.ai preview). The buttons above always work as a manual backup.",
};

const SEARCH_PLACEHOLDER = {
  es: '🔍 Buscar ítems… (ej: cobre, roble, escalera, cofre)',
  en: '🔍 Search items… (e.g. copper, oak, stairs, chest)',
};

function applyLanguage(){
  document.documentElement.lang = LANG;

  document.querySelectorAll('[data-es][data-en]').forEach(el=>{
    const text = LANG==='en' ? el.dataset.en : el.dataset.es;
    if(el.classList.contains('sec-name')){
      el.textContent = (el.dataset.icon?el.dataset.icon+' ':'') + text;
    } else {
      el.textContent = text;
    }
  });

  document.querySelectorAll('.item-row').forEach(row=>{
    const cb = row.querySelector('.slot');
    if(!cb) return;
    const obj = LABELS_BY_ID[cb.id];
    if(!obj) return;
    const label = LANG==='en' ? obj.en : obj.es;
    const labelSpan = row.querySelector('.item-label');
    if(labelSpan) labelSpan.textContent = label;
    row.dataset.label = label.toLowerCase();
  });

  searchInput.placeholder = SEARCH_PLACEHOLDER[LANG];
  searchClearBtn.title = LANG==='en' ? 'Clear search' : 'Limpiar búsqueda';
  document.getElementById('saveBtn').textContent = LANG==='en' ? '💾 SAVE PROGRESS' : '💾 GUARDAR PROGRESO';
  document.getElementById('loadBtn').textContent = LANG==='en' ? '📂 LOAD PROGRESS' : '📂 CARGAR PROGRESO';
  document.getElementById('dimLegend').innerHTML = LEGEND_HTML[LANG];
  document.getElementById('footerNote').textContent = FOOTER_TEXT[LANG];
  document.getElementById('autosaveNote').textContent = AUTOSAVE
    ? (LANG==='en' ? '🟢 Autosave is active in this browser.' : '🟢 Guardado automático activo en este navegador.')
    : (LANG==='en' ? "🟠 Autosave isn't available here (restricted preview) — use the buttons above." : '🟠 Guardado automático no disponible aquí (vista previa restringida) — usa los botones de arriba.');
  document.getElementById('dateStamp').textContent = new Date().toLocaleDateString(LANG==='en'?'en-US':'es-ES');
  document.getElementById('langEs').classList.toggle('active-lang', LANG==='es');
  document.getElementById('langEn').classList.toggle('active-lang', LANG==='en');

  document.getElementById('crossEditorInput').placeholder = LANG==='en' ? 'Item name…' : 'Nombre del ítem…';
  refreshItemsDatalist();
  renderCross();
  if(selectedSlot){ openCrossEditor(selectedSlot.arm, selectedSlot.side, selectedSlot.depth, selectedSlot.idx); }

  updateCounts();
  runSearch();
}

document.getElementById('langSwitch').addEventListener('click', e=>{
  const btn = e.target.closest('[data-lang]');
  if(!btn || btn.dataset.lang===LANG) return;
  LANG = btn.dataset.lang;
  try{ localStorage.setItem('mc_lang_pref', LANG); }catch(err){}
  applyLanguage();
});

autoLoad();
applyLanguage();

/* ================= SAVE / LOAD ================= */

function flashStatus(msg){
  const s = document.getElementById('saveStatus');
  s.textContent = msg;
  setTimeout(()=>{ if(s.textContent===msg) s.textContent=''; }, 2500);
}

document.getElementById('saveBtn').addEventListener('click', ()=>{
  const checked = [...document.querySelectorAll('.slot')]
    .filter(b=>b.checked).map(b=>b.id);
  const data = {
    savedAt: new Date().toISOString(),
    checked,
    layout: CROSS_LAYOUT,
  };
  const blob = new Blob([JSON.stringify(data, null, 2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'minecraft-checklist-progreso.json';
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
  flashStatus(LANG==='en' ? `Saved ✓ (${checked.length} items)` : `Guardado ✓ (${checked.length} ítems)`);
});

document.getElementById('loadBtn').addEventListener('click', ()=>{
  document.getElementById('loadInput').click();
});

document.getElementById('loadInput').addEventListener('change', e=>{
  const file = e.target.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    try{
      const data = JSON.parse(reader.result);
      const ids = new Set(data.checked || []);
      let restored = 0;
      document.querySelectorAll('.slot').forEach(b=>{
        const on = ids.has(b.id);
        b.checked = on;
        b.closest('.item-row').classList.toggle('done', on);
        if(on) restored++;
      });
      if(data.layout && typeof data.layout==='object'){
        ['N','S','E','W'].forEach(arm=>{
          if(isValidArmData(data.layout[arm])) CROSS_LAYOUT[arm] = data.layout[arm];
          else if(isLegacyArmData(data.layout[arm])) CROSS_LAYOUT[arm] = migrateLegacyArm(data.layout[arm]);
        });
        closeCrossEditor();
        crossSave();
        renderCross();
      }
      updateCounts();
      autoSave();
      flashStatus(LANG==='en' ? `Loaded ✓ (${restored} items)` : `Cargado ✓ (${restored} ítems)`);
    }catch(err){
      flashStatus(LANG==='en' ? 'Error reading file ✕' : 'Error al leer el archivo ✕');
    }
  };
  reader.readAsText(file);
  e.target.value = '';
});
